void addValue(Set entities, def value) {
  if (value != null && value != "") {
    entities.add(value);
  }
}

boolean isKubernetes = false;
if (ctx.json?.resource?.type != null) {
  String typ = ctx.json.resource.type;
  isKubernetes = (typ == "k8s_cluster" || typ == "gke_cluster" || typ == "kubernetes");
}

// Using tree set to ensure a sorting is kept (testing purposes)
TreeSet entities = new TreeSet();

addValue(entities, ctx.json?.protoPayload?.request?.parent);
if (!isKubernetes) {
  addValue(entities, ctx.json?.protoPayload?.resourceName);
  addValue(entities, ctx.json?.protoPayload?.response?.user);
}

HashMap authInfo = ctx.json?.protoPayload?.authenticationInfo ?: new HashMap();
if (!isKubernetes) {
  addValue(entities, authInfo.principalEmail);
}
addValue(entities, authInfo.principalSubject);
addValue(entities, authInfo.serviceAccountKeyName);
if (authInfo.serviceAccountDelegationInfo instanceof List) {
  for (def i: authInfo.serviceAccountDelegationInfo) {
    addValue(entities, i.principalSubject);
    addValue(entities, i.firstPartyPrincipal?.principalEmail);
    addValue(entities, i.thirdPartyPrincipal?.principalEmail);
  }
}

String serviceName = ctx.json?.protoPayload?.serviceName ?: '';
if (serviceName == "compute.googleapis.com") {
  if (ctx.json?.protoPayload?.request?.networkInterfaces instanceof List) {
    for (def e: ctx.json.protoPayload.request.networkInterfaces) {
      addValue(entities, e.network);
    }
  }
  if (ctx.json?.protoPayload?.request?.serviceAccounts instanceof List) {
    for (def e: ctx.json.protoPayload.request.serviceAccounts) {
      addValue(entities, e.email);
    }
  }
  if (ctx.json?.protoPayload?.request?.disks instanceof List) {
    for (def e: ctx.json.protoPayload.request.disks) {
      addValue(entities, e.source);
    }
  }
} else if (serviceName == "cloudresourcemanager.googleapis.com") {
  if (ctx.json?.protoPayload?.request?.policy?.bindings instanceof List) {
    for (def e: ctx.json.protoPayload.request.policy.bindings) {
      addValue(entities, e.role);
      for (def m: e.members) {
        addValue(entities, m);
      }
    }
  }
  if (ctx.json?.protoPayload?.response?.bindings instanceof List) {
    for (def e: ctx.json.protoPayload.response.bindings) {
      addValue(entities, e.role);
      for (def m: e.members) {
        addValue(entities, m);
      }
    }
  }
} else if (serviceName == "iamcredentials.googleapis.com") {
  if (ctx.json?.protoPayload?.metadata?.identityDelegationChain instanceof List) {
    for (def e: ctx.json.protoPayload.metadata.identityDelegationChain) {
      addValue(entities, e);
    }
  }
}

if (entities.size() > 0) {
  ctx.related = ctx.related ?: [:];
  ctx.related.entity = entities;
}

void addNestedValue(def currentCtx, String path, def value) {
  if (value == null || value == "") {
    return;
  }
  String[] parts = path.splitOnToken('.');
  for (int i = 0; i < parts.length - 1; i++) {
    if (currentCtx[parts[i]] == null) {
      currentCtx[parts[i]] = [:];
    }
    currentCtx = currentCtx[parts[i]];
  }
  String lastPart = parts[parts.length - 1];
  if (currentCtx[lastPart] == null) {
    currentCtx[lastPart] = [];
  }
  if (!currentCtx[lastPart].contains(value)) {
    currentCtx[lastPart].add(value);
  }
}

// Classify actor entities
if (ctx.actor?.entity?.id instanceof List) {
  for (def actorId : ctx.actor.entity.id) {
    if (actorId == null || actorId == "") {
      continue;
    }
    String actor = actorId.toString();

    // Service accounts: serviceAccount:* or *.gserviceaccount.com (includes cloudservices and iam)
    if (actor.startsWith("serviceAccount:") || actor.contains(".gserviceaccount.com")) {
      addNestedValue(ctx, "service.entity.id", actor);
    }
    // Service account paths: projects/*/serviceAccounts/*
    else if (actor.contains("/serviceAccounts")) {
      addNestedValue(ctx, "service.entity.id", actor);
    }
    // User accounts: user:* or email addresses (not service accounts)
    else if (actor.startsWith("user:") || (actor.contains("@") && !actor.contains(".gserviceaccount.com"))) {
      addNestedValue(ctx, "user.entity.id", actor);
    }
    // Compute instances: projects/*/zones/*/instances/*
    else if (actor.contains("/instances")) {
      addNestedValue(ctx, "host.entity.id", actor);
    }
    // GCP service or API names: *.googleapis.com (but not principal:// or workloadIdentityPools)
    else if (actor.contains(".googleapis.com") && !actor.startsWith("principal://") && !actor.contains("/workloadIdentityPools")) {
      addNestedValue(ctx, "service.entity.id", actor);
    }
    // Everything else (repo:, workloadIdentityPools, principal://, etc.)
    else {
      addNestedValue(ctx, "entity.id", actor);
    }
  }
}

// Classify target entities
if (ctx.target?.entity?.id instanceof List) {
  for (def targetId : ctx.target.entity.id) {
    if (targetId == null || targetId == "") {
      continue;
    }
    String target = targetId.toString();

    // Compute instances
    if (target.contains("/instances")) {
      addNestedValue(ctx, "host.target.entity.id", target);
    }
    // Service accounts: projects/*/serviceAccounts/* or email addresses ending with .gserviceaccount.com
    else if (target.contains("/serviceAccounts") || 
             (target.contains("@") && target.contains(".gserviceaccount.com"))) {
      addNestedValue(ctx, "service.target.entity.id", target);
    }
    // IAM principals (users, groups)
    else if (target.contains("/users") || 
             target.contains("/groups") ||
             (target.contains("@") && target.contains("/members"))) {
      addNestedValue(ctx, "user.target.entity.id", target);
    }
    // GCP service resources
    else if (target.contains("/machineTypes") ||
             target.contains("/deployments") ||
             target.contains("/services") ||
             target.contains("/policies") ||
             target.contains("/operations") ||
             target.contains("/subnetworks") ||
             target.contains("/networkEdgeSecurityServices") ||
             target.contains("/functions") ||
             target.contains("/buckets") ||
             target.contains("/datasets") ||
             target.contains("/tables") ||
             target.contains("/disks") ||
             target.contains("/networks") ||
             target.contains("/firewalls") ||
             target.contains("/backendServices") ||
             target.contains("/forwardingRules") ||
             target.contains("/healthChecks") ||
             target.contains("/sslCertificates") ||
             target.contains("/targetPools") ||
             target.contains("/urlMaps") ||
             target.contains(".googleapis.com")) {
      addNestedValue(ctx, "service.target.entity.id", target);
    }
    // Everything else (projects, zones, workloadIdentityPools, etc.)
    else {
      addNestedValue(ctx, "entity.target.id", target);
    }
  }
}

void addValue(Set entities, def value) {
  if (value != null && value != "") {
    entities.add(value);
  }
}

boolean isKubernetes = false;
if (ctx.json?.resource?.type != null) {
  String typ = ctx.json.resource.type;
  isKubernetes = (typ == "k8s_cluster" || typ == "gke_cluster" || typ == "kubernetes");
}

// Using tree set to ensure a sorting is kept (testing purposes)
TreeSet entities = new TreeSet();

addValue(entities, ctx.json?.protoPayload?.request?.parent);
if (!isKubernetes) {
  addValue(entities, ctx.json?.protoPayload?.resourceName);
  addValue(entities, ctx.json?.protoPayload?.response?.user);
}

HashMap authInfo = ctx.json?.protoPayload?.authenticationInfo ?: new HashMap();
if (!isKubernetes) {
  addValue(entities, authInfo.principalEmail);
}
addValue(entities, authInfo.principalSubject);
addValue(entities, authInfo.serviceAccountKeyName);
if (authInfo.serviceAccountDelegationInfo instanceof List) {
  for (def i: authInfo.serviceAccountDelegationInfo) {
    addValue(entities, i.principalSubject);
    addValue(entities, i.firstPartyPrincipal?.principalEmail);
    addValue(entities, i.thirdPartyPrincipal?.principalEmail);
  }
}

String serviceName = ctx.json?.protoPayload?.serviceName ?: '';
if (serviceName == "compute.googleapis.com") {
  if (ctx.json?.protoPayload?.request?.networkInterfaces instanceof List) {
    for (def e: ctx.json.protoPayload.request.networkInterfaces) {
      addValue(entities, e.network);
    }
  }
  if (ctx.json?.protoPayload?.request?.serviceAccounts instanceof List) {
    for (def e: ctx.json.protoPayload.request.serviceAccounts) {
      addValue(entities, e.email);
    }
  }
  if (ctx.json?.protoPayload?.request?.disks instanceof List) {
    for (def e: ctx.json.protoPayload.request.disks) {
      addValue(entities, e.source);
    }
  }
} else if (serviceName == "cloudresourcemanager.googleapis.com") {
  if (ctx.json?.protoPayload?.request?.policy?.bindings instanceof List) {
    for (def e: ctx.json.protoPayload.request.policy.bindings) {
      addValue(entities, e.role);
      for (def m: e.members) {
        addValue(entities, m);
      }
    }
  }
  if (ctx.json?.protoPayload?.response?.bindings instanceof List) {
    for (def e: ctx.json.protoPayload.response.bindings) {
      addValue(entities, e.role);
      for (def m: e.members) {
        addValue(entities, m);
      }
    }
  }
} else if (serviceName == "iamcredentials.googleapis.com") {
  if (ctx.json?.protoPayload?.metadata?.identityDelegationChain instanceof List) {
    for (def e: ctx.json.protoPayload.metadata.identityDelegationChain) {
      addValue(entities, e);
    }
  }
}

if (entities.size() > 0) {
  ctx.related = ctx.related ?: [:];
  ctx.related.entity = entities;
}

def first = (ctx.json.operation.first == null) ? false : ctx.json.operation.first;
def last = (ctx.json.operation.last == null) ? false : ctx.json.operation.last;
if (first && last) {
  return;
}
if (ctx.event.category == null) {
  ctx.event.category = new ArrayList();
}
if (ctx.event.type == null) {
  ctx.event.type = new ArrayList();
}
ctx.event.category.add('session');
if (first == true && last == false) {
  ctx.event.type.add('start');
}
if (first == false && last == true) {
  ctx.event.type.add('end');
}

boolean drop(Object o) {
  if (o == null || o == "") {
    return true;
  } else if (o instanceof Map) {
    def m = ((Map) o);
    def it = m.entrySet().iterator();
    while (it.hasNext()) {
      def e = ((Map.Entry) it.next());
      def key = ((String) e.getKey());
      def value = e.getValue();
      Pattern onlyDotsRegex = /^\.+$/;
      if (onlyDotsRegex.matcher(key).matches() || drop(value)) {
        it.remove();
      }
    }
    return (m.size() == 0);
  } else if (o instanceof List) {
    def l = ((List) o);
    l.removeIf(v -> drop(v));
    return (l.length == 0);
  }
  return false;
}
drop(ctx);
